<script setup lang="ts">
import { computed } from 'vue';
import AnalyticsChart from './AnalyticsChart.vue';
import { chartBase, day, nf, time } from '../city-analytics';
const props=defineProps<{report:any}>();
const summary=computed(()=>props.report.summary??{}),ops=computed(()=>summary.value.operations),safety=computed(()=>summary.value.safety);
const bar=computed(()=>{const rows=ops.value?.enterprises??[];return {...chartBase,grid:{left:155,right:40,top:12,bottom:48},xAxis:{type:'value',name:'里程（km）',nameLocation:'middle',nameGap:30,splitLine:chartBase.yAxis.splitLine},yAxis:{type:'category',inverse:true,data:rows.slice(0,12).map((x:any)=>x.name),axisLabel:{width:140,overflow:'truncate',fontSize:10},axisLine:{show:false},axisTick:{show:false}},series:[{type:'bar',barMaxWidth:18,itemStyle:{color:'#327cff',borderRadius:[0,3,3,0]},data:rows.slice(0,12).map((x:any)=>x.mileage),label:{show:true,position:'right',formatter:(x:any)=>nf(x.value)}}]};});
const eventBar=computed(()=>({...chartBase,grid:{left:130,right:40,top:12,bottom:48},xAxis:{type:'value',name:'事件数（起）',nameLocation:'middle',nameGap:30,minInterval:1,splitLine:chartBase.yAxis.splitLine},yAxis:{type:'category',inverse:true,data:(safety.value?.types??[]).slice(0,12).map((x:any)=>x.name),axisLabel:{width:110,overflow:'truncate',fontSize:11},axisLine:{show:false},axisTick:{show:false}},series:[{type:'bar',barMaxWidth:18,itemStyle:{color:'#327cff'},data:(safety.value?.types??[]).slice(0,12).map((x:any)=>x.value),label:{show:true,position:'right'}}]}));
</script>
<template><article class="ca-report-paper"><h2>{{report.title}}</h2><p class="ca-note" style="text-align:center">统计周期 {{summary.period?.from||day(report.periodStart)}} — {{summary.period?.to||day(report.periodEnd)}}<br/>统计范围 {{summary.scopeName||report.enterprise?.name||report.organization?.name}}</p><p v-if="summary.schemaVersion!==2" class="ca-note">历史报表按生成时的统计口径留存，未重新计算。</p>
 <template v-if="ops"><div class="ca-report-summary"><div>运行里程<strong>{{nf(ops.kpis?.mileage)}}<small> km</small></strong></div><div>运行记录<strong>{{nf(ops.kpis?.trips,0)}}<small> 条</small></strong></div><div>运行时长<strong>{{nf(ops.kpis?.durationHours)}}<small> h</small></strong></div></div><h3>一、企业运行情况</h3><table class="ca-detail-table"><thead><tr><th>企业名称</th><th>里程（km）</th><th>记录（条）</th><th>时长（h）</th></tr></thead><tbody><tr v-for="e in ops.enterprises??[]" :key="e.id"><td>{{e.name}}</td><td>{{nf(e.mileage)}}</td><td>{{nf(e.trips,0)}}</td><td>{{nf(e.durationHours)}}</td></tr><tr v-if="!ops.enterprises?.length"><td colspan="4">{{summary.schemaVersion===2?'生成时暂无企业明细':'该历史报表未保存企业明细'}}</td></tr></tbody></table><h3>二、运行里程分布</h3><AnalyticsChart v-if="ops.enterprises?.some((e:any)=>e.mileage!=null)" :option="bar" :height="`${Math.max(220,Math.min(480,(ops.enterprises?.length??0)*46+60))}px`" aria-label="报表企业运行里程分布图"/><p v-else class="ca-note">{{summary.schemaVersion===2?'暂无可用于绘图的有效里程。':'该历史报表未保存企业里程分布。'}}</p><p v-if="ops.quality?.missingDays" class="ca-note">周期内{{ops.quality.missingDays}}天没有运行记录；缺失值不补为0。</p></template>
 <template v-if="safety"><h3>{{ops?'三':'一'}}、安全事件统计</h3><div v-if="summary.schemaVersion===2" class="ca-report-summary"><div>事件总数<strong>{{nf(safety.kpis?.total,0)}}<small> 起</small></strong></div><div>已闭环<strong>{{nf(safety.kpis?.closed,0)}}<small> 起</small></strong></div><div>闭环率<strong>{{nf(safety.kpis?.closureRate)}}<small> %</small></strong></div></div><template v-else><div class="ca-report-summary"><div>安全告警<strong>{{nf(safety.kpis?.alerts,0)}}<small> 条</small></strong></div><div>事故<strong>{{nf(safety.kpis?.accidents,0)}}<small> 起</small></strong></div><div>违规记录<strong>{{nf(safety.kpis?.violations,0)}}<small> 条</small></strong></div></div><p class="ca-note">告警闭环率（历史口径）：{{nf(safety.kpis?.alerts>0?safety.kpis?.closureRate:null)}}%</p></template><table v-if="safety.enterprises?.length" class="ca-detail-table"><thead><tr><th>企业</th><th>事件数</th><th>待核查</th><th>处置中</th><th>已闭环</th></tr></thead><tbody><tr v-for="e in safety.enterprises??[]" :key="e.id"><td>{{e.name}}</td><td>{{nf(e.total,0)}}</td><td>{{nf(e.pending,0)}}</td><td>{{nf(e.handling,0)}}</td><td>{{nf(e.closed,0)}}</td></tr></tbody></table><AnalyticsChart v-if="safety.types?.length" :option="eventBar" height="260px" aria-label="报表安全事件类型分布图"/><p class="ca-note">{{summary.schemaVersion===2?'同一来源事件去重，闭环率按本周期事件计算。':'历史报表的告警、事故和违规采用当时口径，未提供的指标以 — 显示。'}}</p></template>
 <p class="ca-note">生成时间 {{time(report.generatedAt)}} · {{report.generatedByName}}<br/>生成后数据留存，预览与导出读取同一份内容。</p></article></template>
